{
  "title": "How a microwave heats food",
  "screens": [
    {
      "title": "A surprisingly selective heat",
      "text": "When you heat a bowl of soup in the microwave, the broth turns piping hot while the ceramic bowl stays mostly cool to the touch. Unlike a standard oven that roasts everything in hot air, a microwave targets only specific ingredients inside your meal.",
      "imagePrompt": "A person carefully touching a cool ceramic bowl filled with steaming hot soup inside an open microwave oven."
    },
    {
      "title": "Invisible waves of energy",
      "text": "Inside the machine, a special transmitter sends out invisible electromagnetic waves called microwaves. These waves pass straight through air, glass, and most plastics without warming them up at all.",
      "imagePrompt": "A cross-section illustration of a microwave oven showing waves traveling from a metal transmitter directly toward a meal on a turntable."
    },
    {
      "title": "Water molecules act like compasses",
      "text": "Most food contains lots of water. A water molecule has positive and negative ends, much like a tiny magnetic compass needle. When the microwave's electric field flips back and forth billions of times a second, the water molecules twist rapidly to keep up.",
      "imagePrompt": "A microscopic view of tiny water molecules with positive and negative ends rapidly spinning back and forth."
    },
    {
      "title": "Friction creates the heat",
      "text": "As these trillions of water molecules twist and bump against each other, their motion creates friction. Think of rubbing your hands together vigorously on a freezing day—motion turns directly into heat, warming the moisture throughout your food.",
      "imagePrompt": "Two hands rubbing together vigorously to show friction, paired with water molecules bumping together and radiating warmth."
    },
    {
      "title": "Heat spreads from within",
      "text": "Because the waves only penetrate about an inch deep, the hot outer water transfers warmth toward the center through regular conduction. That is why very thick or frozen meals need extra resting time to let the heat spread evenly to the middle.",
      "imagePrompt": "A thick burrito cut in half, showing heat rings traveling inward from the steaming outer layer to the center."
    }
  ],
  "check": {
    "question": "Why does a completely dry paper towel remain cool when run in a microwave, while a damp one gets steaming hot?",
    "options": [
      {
        "text": "The dry paper reflects all the microwaves back into the machine.",
        "isCorrect": false,
        "feedback": "Dry paper doesn't reflect the waves; it simply lets them pass straight through without absorbing their energy."
      },
      {
        "text": "The damp towel contains water molecules that twist and generate heat.",
        "isCorrect": true,
        "feedback": "Correct! Microwaves specifically cause water molecules to flip rapidly, producing heat through microscopic friction."
      },
      {
        "text": "Water traps heat from the hot air circulating inside the microwave.",
        "isCorrect": false,
        "feedback": "A microwave heats food directly with waves, not by circulating hot air like a conventional oven."
      }
    ]
  },
  "recap": [
    "Microwaves pass through air and containers to target water molecules in food.",
    "Rapidly flipping electric waves force water molecules to twist back and forth.",
    "This intense molecule friction generates heat, which then spreads throughout the dish."
  ],
  "goFurther": {
    "overviewCourse": "Physics of Everyday Things",
    "relatedQuestions": [
      "Why can't you put metal in the microwave?",
      "Why do microwaves leave cold spots in food?",
      "Does microwaving food destroy its nutrients?"
    ]
  }
}

{
